r"""
Crescopus - Help label and grower topics

  - The menu link to the help pages now says "Help" (uses modcontent v0.2.3).
  - New crescopus_pages_growers.py: 14 grower topics written from a neutral
    point of view ("the grower", "the builder"), loaded as drafts.
  - load_pages.py gains a --growers option to load them.
  - Includes the CrescoHelp change, so it works whether or not you have
    pushed apply_crescohelp.py yet.

BEFORE YOU RUN THIS
  Run apply_modcontent_help_label.py in modcontent and push the v0.2.3 tag first.

HOW TO USE
  1. Save this file in your Crescopus project folder (next to wsgi.py).
  2. In PowerShell, in that folder, with your venv active:
         python apply_grower_help.py
         pip install -r requirements.txt
         python load_pages.py <your-user-id> --growers --check
         python load_pages.py <your-user-id> --growers
  3. The pages arrive as drafts. Edit, remove the two [CONFIRM] notes, then
     submit and approve them in /content/editor.
  4. Any file it replaces is copied first to _backup_apply_grower_help\.

It checks each file matches the version on GitHub first. If you have changed
one locally since your last push, it stops without writing anything.
Your .env is never read or changed.
"""
import base64, hashlib, os, shutil, sys

# (path, new content, sha256s of the versions it may replace)
FILES = [
    ('app/__init__.py', '', ['2c16ffd3118b8885924c96e9ceac057ef71ee30858f09995e4ad5be35a244822', '700f96f47f6629cfabb33cef049550947ec4012bdfaa9c4cb5ad8c901e60dceb']),
    ('requirements.txt', '', ['fe703ed23eeee8f45a9d50c3657ae71b3291cc365faf617801edd1efec55ca09', 'b39cc1c79e2255aa58dfca89dc17f5818992af1bd6e64eff201ffb8fabb56ab5']),
    ('load_pages.py', '', ['bccfcbe8f7f624145c7f54b639b8cc0e9ae20027b3e6ae02583b386f62d5b324']),
    ('crescopus_pages_growers.py', '', []),
]
BACKUP = '_backup_apply_grower_help'
NEXT = 'pip install -r requirements.txt, load the grower pages (see the top of this file), restart python wsgi.py, then commit and push.'

def sha(data):
    return hashlib.sha256(data).hexdigest()

def main():
    root = os.path.dirname(os.path.abspath(__file__))
    if not (os.path.isfile(os.path.join(root, *['wsgi.py'])) and os.path.isfile(os.path.join(root, *['app', '__init__.py']))):
        sys.exit("Stopped: put this file in the Crescopus project folder, then run it again.")
    clashes = []
    for rel, b64, expected in FILES:
        path = os.path.join(root, *rel.split("/"))
        if not os.path.exists(path):
            continue
        new = base64.b64decode(b64)
        with open(path, "rb") as fh:
            current = fh.read()
        current_norm = current.replace(b"\r\n", b"\n")
        if current == new or current_norm == new:
            continue
        if not expected or sha(current_norm) not in expected:
            clashes.append(rel)
    if clashes:
        print("Stopped - nothing written. These files differ from the version this update was built from:")
        for c in clashes:
            print("   " + c)
        sys.exit("Push or share your latest changes and ask for the update to be rebuilt.")

    backup = os.path.join(root, BACKUP)
    changed = 0
    for rel, b64, expected in FILES:
        path = os.path.join(root, *rel.split("/"))
        data = base64.b64decode(b64)
        status = "new     "
        if os.path.exists(path):
            with open(path, "rb") as fh:
                current = fh.read()
            if current == data or current.replace(b"\r\n", b"\n") == data:
                print("same     " + rel)
                continue
            dest = os.path.join(backup, *rel.split("/"))
            os.makedirs(os.path.dirname(dest), exist_ok=True)
            shutil.copy2(path, dest)
            status = "updated "
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "wb") as fh:
            fh.write(data)
        changed += 1
        print(status + " " + rel)
    print("\nDone - %d of %d files written." % (changed, len(FILES)))
    if os.path.isdir(backup):
        print("Originals of replaced files are in " + BACKUP + os.sep)
    if NEXT:
        print("Next: " + NEXT)

if __name__ == "__main__":
    main()
